<?php
declare(strict_types=1);
use CoreCMS\Core\Url;
use CoreCMS\Modules\Tourism\TourismManager;
require_once dirname(__DIR__).'/Admin/TourismManager.php';
return static function(PDO $db,array $params,array $request,array $module):string{
 CoreCMS\Core\Auth::startSession();$manager=new TourismManager($db);$tour=$manager->findTour((string)($params['slug']??''));$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$base=Url::to('/turlar');
 if(!$tour||$tour['status']!=='published'){http_response_code(404);return '<h1>Tur bulunamadı</h1>';}
 $html='<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($tour['seo_title']?:$tour['title']).'</title><meta name="description" content="'.$e($tour['seo_description']?:substr(strip_tags($tour['description']),0,155)).'"><link rel="stylesheet" href="'.Url::to('/modules/tourism/assets/css/tourism.css').'"></head><body class="tm-site"><header class="tm-header"><a class="tm-brand" href="'.$base.'">KEŞFET<span>.</span></a><a href="'.$base.'">← Tüm turlar</a></header><main class="tm-container"><article class="tm-detail">';
 $images=$tour['gallery'];if($tour['cover_image'])array_unshift($images,$tour['cover_image']);if($images){$html.='<div class="tm-gallery">';foreach(array_slice(array_unique($images),0,8) as $img)$html.='<img src="'.$e($img).'" alt="'.$e($tour['title']).'">';$html.='</div>';}
 $html.='<span class="tm-kicker">'.$e($tour['destination_name']??''). ' · '.$e($tour['category']).'</span><h1>'.$e($tour['title']).'</h1><div class="tm-detail-meta"><b>'.number_format((float)$tour['price'],0,',','.').' '.$e($tour['currency']).' / kişi</b><span>'.$e($tour['duration_hours']).' saat</span><span>'.$e($tour['min_guests']).'–'.$e($tour['max_guests']).' kişi</span></div><div class="tm-detail-grid"><section><div class="tm-description">'.nl2br($e($tour['description'])).'</div>';
 if($tour['itinerary']){$html.='<h2>Tur programı</h2><ol class="tm-itinerary">';foreach($tour['itinerary'] as $step)$html.='<li>'.$e($step).'</li>';$html.='</ol>';}
 foreach(['included'=>'Fiyata dahil','not_included'=>'Fiyata dahil olmayanlar'] as $field=>$title)if(trim((string)$tour[$field])!=='')$html.='<h2>'.$title.'</h2><div class="tm-description">'.nl2br($e($tour[$field])).'</div>';
 $html.='</section><aside class="tm-booking" id="rezervasyon"><h2>Rezervasyon talebi</h2><p>Uygun kalkış tarihini seçerek talebinizi gönderin.</p>';
 if($tour['departures']){$html.='<form method="post" action="'.$base.'/rezervasyon"><input type="hidden" name="tour_id" value="'.(int)$tour['id'].'"><label>Kalkış tarihi<select name="departure_id" required><option value="">Tarih seçin</option>';foreach($tour['departures'] as $dep){$available=(int)$dep['seats_total']-(int)$dep['seats_reserved'];if($available>0)$html.='<option value="'.(int)$dep['id'].'">'.$e($dep['departure_at']).' · '.$available.' yer</option>';}$html.='</select></label><label>Yetişkin<input type="number" name="adults" min="1" max="'.(int)$tour['max_guests'].'" value="1" required></label><label>Çocuk<input type="number" name="children" min="0" max="'.(int)$tour['max_guests'].'" value="0"></label><label>Ad soyad<input name="name" maxlength="160" required></label><label>E-posta<input type="email" name="email" maxlength="190" required></label><label>Telefon<input name="phone" maxlength="60"></label><label>Notunuz<textarea name="message" rows="3" maxlength="3000"></textarea></label><label class="tm-honey">Web sitesi<input name="website" tabindex="-1" autocomplete="off"></label>'.CoreCMS\Core\Csrf::field().'<button class="tm-button">Rezervasyon talebi gönder</button></form>';}else $html.='<div class="tm-empty">Şu anda açık kalkış tarihi bulunmuyor. Lütfen daha sonra tekrar kontrol edin.</div>';
 $html.='</aside></div></article></main><footer class="tm-footer">KEŞFET. · '.date('Y').'</footer></body></html>';return $html;
};
